using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        // Collect all errors
        var errors = new List<(string Project, string Code, string Message, string File, int Line)>();
        build.VisitAllChildren<Error>(e =>
        {
            var proj = "";
            var node = e.Parent;
            while (node != null)
            {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }
            errors.Add((proj, e.Code ?? "", e.Text ?? "", e.File ?? "", e.LineNumber));
        });

        // Collect all warnings
        var warnings = new List<(string Project, string Code, string Message)>();
        build.VisitAllChildren<Warning>(w =>
        {
            var proj = "";
            var node = w.Parent;
            while (node != null)
            {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }
            warnings.Add((proj, w.Code ?? "", w.Text ?? ""));
        });

        Console.WriteLine("=== BUILD ERRORS ===");
        foreach (var g in errors.GroupBy(e => e.Project))
        {
            Console.WriteLine($"\nProject: {g.Key}");
            foreach (var e in g)
            {
                Console.WriteLine($"  [{e.Code}] {e.File}({e.Line}): {e.Message}");
            }
        }

        if (warnings.Any())
        {
            Console.WriteLine("\n=== BUILD WARNINGS ===");
            foreach (var g in warnings.GroupBy(w => w.Project))
            {
                Console.WriteLine($"\nProject: {g.Key}");
                foreach (var w in g)
                {
                    Console.WriteLine($"  [{w.Code}] {w.Message}");
                }
            }
        }

        // Check project dependencies / references
        Console.WriteLine("\n=== PROJECT STRUCTURE ===");
        build.VisitAllChildren<Project>(p =>
        {
            if (p.Children == null) return;
            Console.WriteLine($"\nProject: {p.Name} (Succeeded={p.Succeeded})");
        });
    }
}
