using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var binlogPath = args.Length > 0 ? args[0] : "build.binlog";
        var build = BinaryLog.ReadBuild(binlogPath);

        // Check all messages related to project references and restore
        Console.WriteLine("=== ALL ERRORS (with parent hierarchy) ===");
        build.VisitAllChildren<Error>(e =>
        {
            var hierarchy = new List<string>();
            var node = e.Parent;
            while (node != null)
            {
                hierarchy.Add($"{node.GetType().Name}: {node.ToString()?.Substring(0, Math.Min(node.ToString()?.Length ?? 0, 100))}");
                node = node.Parent;
            }
            hierarchy.Reverse();
            foreach (var h in hierarchy)
                Console.WriteLine($"  {h}");
            Console.WriteLine($"  ERROR [{e.Code}] {e.File}({e.LineNumber}): {e.Text}");
            Console.WriteLine();
        });

        // Look for failed targets and tasks
        Console.WriteLine("=== FAILED PROJECTS ===");
        build.VisitAllChildren<Project>(p =>
        {
            // Check if any child target failed
            var hasErrors = false;
            p.VisitAllChildren<Error>(e => hasErrors = true);
            if (hasErrors)
            {
                Console.WriteLine($"  FAILED: {p.Name} | {p.ProjectFile}");
            }
        });

        // Look for NuGet restore issues
        Console.WriteLine("\n=== NUGET/RESTORE MESSAGES ===");
        build.VisitAllChildren<Message>(m =>
        {
            if (m.Text != null && (m.Text.Contains("NU1") || m.Text.Contains("PackageReference") || m.Text.Contains("Newtonsoft") || m.Text.Contains("restore", StringComparison.OrdinalIgnoreCase)))
            {
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 200))}");
            }
        });

        // Look at warnings
        Console.WriteLine("\n=== WARNINGS ===");
        build.VisitAllChildren<Warning>(w =>
        {
            Console.WriteLine($"  [{w.Code}] {w.Text?.Substring(0, Math.Min(w.Text?.Length ?? 0, 200))}");
        });

        // Check for project-to-project dependencies
        Console.WriteLine("\n=== PROJECT ITEMS (References) ===");
        build.VisitAllChildren<Item>(item =>
        {
            if (item.Name == "ProjectReference" || item.Name == "PackageReference")
            {
                var proj = "";
                var node = item.Parent;
                while (node != null)
                {
                    if (node is Project p) { proj = p.Name; break; }
                    node = node.Parent;
                }
                Console.WriteLine($"  {proj} -> [{item.Name}] {item.Text}");
            }
        });
    }
}
