            {
                var proj = "";
                var node = prop.Parent;
                while (node != null)
                {
                    if (node is Project p) { proj = p.Name; break; }
                    node = node.Parent;
                }
                if (!string.IsNullOrEmpty(proj))
                    Console.WriteLine($"  {proj}: {prop.Name} = {prop.Value}");
            }
        });
    }
}
