                    if (node is Project p) { proj = p.Name; break; }
                    node = node.Parent;
                }
                ai.VisitAllChildren<Item>(item =>
                {
                    Console.WriteLine($"  {proj} -> {item.Text}");
                });
            }
        });

        // Get PackageReference items
        Console.WriteLine("\n=== PACKAGE REFERENCES (from AddItem) ===");
        build.VisitAllChildren<AddItem>(ai =>
        {
            var proj = "";
            var node = ai.Parent;
            while (node != null)
            {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }
            if (ai.Name == "PackageReference")
            {
                ai.VisitAllChildren<Item>(item =>
