                        foreach (var c in item.Children)
                            Console.WriteLine($"    {c}");
                });
            }
        });

        // Source files for Services
        Console.WriteLine("\n=== SOURCE FILES FOR Services.csproj ===");
        build.VisitAllChildren<CscTask>(t =>
