            {
                if (param.Name == "Sources" && param.Children != null)
                {
                    foreach (var c in param.Children)
                        Console.WriteLine($"  {c}");
                }
            });
        });

        // Check if Api.csproj compiled at all
        Console.WriteLine("\n=== Api.csproj CSC TASK ===");
        bool foundApiCsc = false;
        build.VisitAllChildren<CscTask>(t =>
        {
            var proj = "";
            var node = t.Parent;
            while (node != null)
            {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }
            if (proj == "Api.csproj") foundApiCsc = true;
        });
        Console.WriteLine(foundApiCsc ? "  Api.csproj has Csc task" : "  Api.csproj has NO Csc task (skipped due to dependency failure)");
    }
