using System;
using System.Linq;
using Microsoft.Build.Logging.StructuredLogger;

class Program2
{
    static void Main(string[] args)
    {
        var build = BinaryLog.ReadBuild(args.Length > 0 ? args[0] : "build.binlog");

        // Get source files for Services.csproj
        Console.WriteLine("=== SOURCE FILES ===");
        build.VisitAllChildren<CscTask>(t =>
        {
            var proj = "";
            var node = t.Parent;
            while (node != null)
            {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }

            t.VisitAllChildren<Item>(item =>
            {
                var s = item.ToString();
                if (s.EndsWith(".cs"))
                    Console.WriteLine($"  {proj}: {s}");
            });
        });

        // Get all project references via AddItem
        Console.WriteLine("\n=== ALL PROJECT REFERENCES ===");
        build.VisitAllChildren<AddItem>(ai =>
        {
            if (ai.Name != "ProjectReference") return;
            var proj = "";
            var node = ai.Parent;
            while (node != null)
            {
                if (node is Project p) { proj = p.Name; break; }
                node = node.Parent;
            }
            ai.VisitAllChildren<Item>(item =>
            {
                Console.WriteLine($"  {proj} -> {item.Text}");
            });
        });

        // Check for Newtonsoft in any reference 
        Console.WriteLine("\n=== NEWTONSOFT IN ANY REF ===");
        build.VisitAllChildren<Item>(item =>
        {
            if (item.Text?.Contains("Newtonsoft", StringComparison.OrdinalIgnoreCase) == true)
            {
                Console.WriteLine($"  {item.Name}: {item.Text}");
            }
        });

        // Check NuGet restore output for package references
        Console.WriteLine("\n=== RESTORE DETAILS ===");
        build.VisitAllChildren<Message>(m =>
        {
            if (m.Text?.Contains("Newtonsoft") == true && !m.Text.Contains("Assembly loaded"))
                Console.WriteLine($"  {m.Text.Substring(0, Math.Min(m.Text.Length, 200))}");
        });

        // Get project file content from embedded files
        Console.WriteLine("\n=== EMBEDDED FILES ===");
        build.VisitAllChildren<SourceFileLine>(sf =>
        {
            Console.WriteLine($"  {sf}");
        });
    }
}
